\title[Chebotarev Precision]{Chebotarev Precision: Simultaneous Re-measurement of the Type-Channel Master Table, the Fine-Dial Reduction Theorem, and the Diagnosis of a Sparse-Dial Anomaly}
\author{Aristotle}
\date{October 7, 2026}

\begin{document}

\begin{abstract}
For a Galois number field with group $G$, the \emph{type channel} is the mutual information between a cheap observation of a prime $p$, its residue class modulo a fixed conductor (the \emph{dial}), and an expensive one, the splitting type of $p$ (the cycle type of its Frobenius). Class field theory and the Chebotarev density theorem give this channel a \emph{law value} determined by $G$ alone: $\Ilaw = I(gG';\mathrm{type}(g))$ for $g$ uniform in $G$, where $G'$ is the commutator subgroup. We report the first simultaneous re-measurement of a full master table of such law values. It covers fifteen canonical fields, with one protocol, one seed and the same $295{,}946$ unramified primes below $2^{22}$ for every field. The largest deviation from law is $4.8\times10^{-4}$ bits, twenty times inside a pre-stated budget of $10^{-2}$. We prove the structural results that make a simultaneous measurement meaningful. The first is a uniform-projection theorem, from which thickening invariance follows. The second is coprime flatness, from which simultaneous-measurement invariance for linearly disjoint fields follows. The third is the \emph{fine-dial reduction theorem}: on the fibre-product model of (Frobenius, residue) pairs with a uniform Artin map, $I(r;T)=I(gG';T)$ for every type readout and every dial size. We certify ten law constants to six decimals using $1054/665<\log_2 3<3647/2301$. We add a new row for the Frobenius group $F_{20}$, with law exactly $3/2$ bits, and exhibit a law collision between $F_{20}$ and $C_4$. Finally we diagnose the single anomaly, a historical value $1.0078$ for an $S_3$ field on a sparse dial, as plug-in bias. In the extreme sparse regime this bias provably saturates at the plug-in type entropy.
\end{abstract}

\maketitle

\section{Introduction}

Let $f\in\mathbb{Z}[x]$ be irreducible of degree $n$ with splitting field $K$ and Galois group $G=\mathrm{Gal}(K/\mathbb{Q})$, viewed as a permutation group on the roots. For a prime $p$ not dividing the discriminant, the Frobenius class $\mathrm{Frob}_p$ is defined, and the factorization pattern of $f\bmod p$ is its cycle type. The Chebotarev density theorem says that $\mathrm{Frob}_p$ is equidistributed: the density of primes with $\mathrm{Frob}_p=C$ is $|C|/|G|$.

Abelian information about $\mathrm{Frob}_p$ is visible to congruences. By class field theory there is a conductor $N$ and a surjective Artin map $\varphi:(\mathbb{Z}/N\mathbb{Z})^\times\twoheadrightarrow G^{ab}=G/G'$ with $\mathrm{Frob}_p\, G'=\varphi(p\bmod N)$ for unramified $p\nmid N$. Non-abelian information is not visible to congruences. The \emph{type channel} asks how many bits about the splitting type the residue of $p$ carries. A master table of law values had been built up and compared with measurement field by field. Separate measurements accumulate protocol drift. This paper reports, and puts on a rigorous footing, a single simultaneous audit of the whole table.

\section{Definitions}

A \emph{population} is a finite nonempty set $\Omega$ with the uniform measure. A \emph{readout} is a function $X:\Omega\to A$.

\begin{definition}[Law, entropy, channel]
The law of $X$ is $P_X(a)=|X^{-1}(a)|/|\Omega|$. Its entropy is $H_\Omega(X)=-\sum_a P_X(a)\log_2P_X(a)$. For readouts $X,Y$ let $(X,Y)$ denote the paired readout. The channel is
\[ I_\Omega(X;Y)=H_\Omega(X)+H_\Omega(Y)-H_\Omega(X,Y), \]
and the conditional channel is $I_\Omega(X;Y\mid Z)=\sum_zP_Z(z)\,I_{Z^{-1}(z)}(X;Y)$.
\end{definition}

We use the standard facts that $I$ is symmetric and nonnegative, that it depends on each readout only through the partition the readout induces, and the chain rule $I(T;(X,Y))=I(T;X)+I(T;Y\mid X)$.

\begin{definition}[Coset and type readouts; law value]
Let $G$ be a finite permutation group. The coset readout is $c(g)=gG'$. A type readout is a function of $g$; the canonical ones are the full cycle type and the coarse splitting type
\[ \sigma(g)=(\#\text{fixed points},\ \#\text{points on 2-cycles}), \]
which is the number of roots of $f$ in $\mathbb{F}_p$ together with the number of further roots in $\mathbb{F}_{p^2}$. The law value is $\Ilaw(G,T)=I_G(c;T)$.
\end{definition}

\begin{definition}[Fibre product; uniform dial]
Let $S$ be a population, $c:S\to\kappa$, $R$ a finite set of residue classes and $\varphi:R\to\kappa$. The fibre product is
\[ \Omega(S,R,c,\varphi)=\{(g,r)\in S\times R:\ c(g)=\varphi(r)\}. \]
The dial is \emph{uniform with fibre size $m$} if $m>0$ and $|\{r:\varphi(r)=k\}|=m$ for every $k\in c(S)$.
\end{definition}

The fibre product models the joint law of $(\mathrm{Frob}_p,\,p\bmod N)$. Dirichlet's theorem makes the residue uniform, and Chebotarev for the compositum with the $N$-th cyclotomic field makes the Frobenius uniform subject to the reciprocity constraint $c(g)=\varphi(r)$.

\section{Uniform projection and thickening}

\begin{lemma}\label{lem:count}
Let $\Omega'\subseteq S\times\rho$ lie over $S$, with every $g\in S$ having exactly $m$ points above it. Then for every predicate $P$ on $S$, $|\{w\in\Omega':P(w_1)\}|=m\,|\{g\in S:P(g)\}|$.
\end{lemma}
\begin{proof}
Count fibrewise along $\pr_1$.
\end{proof}

\begin{theorem}[Uniform projection]\label{thm:proj}
Under the hypotheses of Lemma~\ref{lem:count} with $m>0$, $H_{\Omega'}(f\circ\pr_1)=H_S(f)$ for every readout $f$ of $S$. Consequently $I_{\Omega'}(f\circ\pr_1;g\circ\pr_1)=I_S(f;g)$.
\end{theorem}
\begin{proof}
Since $m>0$ the images agree. Lemma~\ref{lem:count} gives $|\Omega'|=m|S|$ and $|f^{-1}(a)\cap\Omega'|=m|f^{-1}(a)\cap S|$, so the laws agree. For the channel, apply the same argument to $f$, $g$ and $(f,g)$.
\end{proof}

\begin{corollary}[Thickening]\label{cor:thick}
For nonempty $R$, $H_{S\times R}(f\circ\pr_1)=H_S(f)$ and $I_{S\times R}(f\circ\pr_1;g\circ\pr_1)=I_S(f;g)$.
\end{corollary}

\section{Coprime flatness and simultaneous measurement}

\begin{lemma}
$P_{(f\circ\pr_1,g\circ\pr_2)}(a,b)=P_f(a)P_g(b)$ on $S\times R$.
\end{lemma}

\begin{theorem}[Additivity]
For nonempty $S,R$: $H_{S\times R}(f\circ\pr_1,g\circ\pr_2)=H_S(f)+H_R(g)$.
\end{theorem}

\begin{theorem}[Coprime flatness]\label{thm:flat}
For any $S,R$ and readouts $f$ of $S$ and $g$ of $R$, $I_{S\times R}(f\circ\pr_1;g\circ\pr_2)=0$.
\end{theorem}
\begin{proof}
The empty cases are trivial. Otherwise Corollary~\ref{cor:thick} gives both marginals (the second via the swap bijection), additivity gives the joint entropy, and the three terms cancel.
\end{proof}

\begin{theorem}[Simultaneous-measurement invariance]\label{thm:sim}
Let $S,R$ be nonempty with readouts $c_A,T_A$ on $S$ and $c_B,T_B$ on $R$. On $S\times R$:
$I(c_A;T_A)=I_S(c_A;T_A)$, $I(c_B;T_B)=I_R(c_B;T_B)$, and $I(c_A;T_B)=I(c_B;T_A)=0$.
\end{theorem}
\begin{proof}
The first two statements are thickening; the last two are coprime flatness.
\end{proof}

\begin{example}
For $x^3+x+1$ ($S_3$) and $x^4-2$ ($D_4$) measured jointly, the own-field channels are $1$ and $\tfrac94-\tfrac38\log_23$, and both cross channels vanish. For $F_{20}\times A_4$ the own-field channels are $\tfrac32$ and $\log_23-\tfrac23$, again with zero crosstalk.
\end{example}

\section{The fine-dial reduction theorem}

\begin{theorem}[Fine-dial reduction]\label{thm:fine}
Let $(S,R,c,\varphi)$ be a uniform dial with fibre product $\Omega$, and let $T$ be any readout of $S$. Then
\[ I_\Omega(r;\,T\circ g)=I_S(c;\,T). \]
\end{theorem}
\begin{proof}
The proof makes the Markov chain $r\to c\to T$ explicit in four steps.
(1) On $\Omega$ the readouts $r$ and $(c,r)$ induce the same partition, since $c(g)=\varphi(r)$. Hence $I(r;T)=I((c,r);T)$.
(2) By the chain rule, $I(T;(c,r))=I(T;c)+I(T;r\mid c)$.
(3) Each $g\in S$ has exactly $m$ points above it in $\Omega$, so Theorem~\ref{thm:proj} gives $I_\Omega(T;c)=I_S(T;c)$.
(4) The fibre over $c=k$ is the product $\{g:c(g)=k\}\times\{r:\varphi(r)=k\}$. By Theorem~\ref{thm:flat} each term of $I(T;r\mid c)$ vanishes.
Combining the steps gives the result.
\end{proof}

\begin{corollary}[Dial independence]
Two uniform dials of any sizes over the same coset readout have identical type channels.
\end{corollary}

\begin{corollary}[Abelian sandwich]
If $S$ is a group with derived subgroup $N$, $c(g)=gN$, and the dial is uniform, then
\[ \max\bigl(0,H_S(T)-\log_2|N|\bigr)\le I_\Omega(r;T)\le\log_2[S:N]. \]
\end{corollary}
\begin{proof}
Reduce to $I_S(c;T)$ by Theorem~\ref{thm:fine}. The upper bound is $I\le H(c)$. For the lower bound, $H(T\mid c)\le\log_2|N|$.
\end{proof}

\begin{corollary}[Coprime residues add nothing]
Append a nonempty set $Q$ of residues independent of Frobenius, so that the residues are $R\times Q$ and the Artin map is $(r,q)\mapsto\varphi(r)$. The dial stays uniform with fibre size $m|Q|$, and $I((r,q);T)=I_S(c;T)=I(r;T)$.
\end{corollary}

\begin{example}\label{ex:23}
For $x^3-x-1$ (discriminant $-23$, group $S_3$) the Artin map is the quadratic character modulo $23$ on the $22$ nonzero residues, with $11$ residues over each coset. The population channel is therefore exactly $1$ bit. For every unramified $p<100$ the number of roots mod $p$ lies in $\{0,1,3\}$, and it equals $1$ exactly when $p$ is a non-residue mod $23$. A direct computation extends this check to all $2{,}261$ unramified primes below $20{,}000$.
\end{example}

\section{The master table to six decimals}

\begin{proposition}\label{prop:log3}
$\dfrac{1054}{665}<\log_23<\dfrac{3647}{2301}$, from $2^{1054}<3^{665}$ and $3^{2301}<2^{3647}$. Also $\log_25<7/3$, from $5^3<2^7$.
\end{proposition}

The closed forms are as follows.
\begin{itemize}
\item $S_3$, $S_4$ and regular $S_3$: the sign is a function of cycle type and a fair coin, so the law is $1$.
\item $A_4$: the law is $\log_23-\tfrac23$, since the two nontrivial cosets consist of 3-cycles, giving $H(c\mid T)=\tfrac23$.
\item $D_4$: with $H(c)=2$, $H(T)=\tfrac52-\tfrac38\log_23$ and $H(c,T)=\tfrac94$, the law is $\tfrac94-\tfrac38\log_23$.
\item $V_4$: the law is $2-\tfrac34\log_23$.
\item $C_4$: the law is $\tfrac32$.
\item $D_6$ on six points: $1.729574$ for the full cycle type and $1.396241$ for the coarse type.
\end{itemize}

\begin{theorem}[Master table precision]
The ten law constants $S_3,S_4,A_4,D_4,V_4,C_4,D_6$ (full), $D_6$ (coarse), regular $S_3$, $F_{20}$ lie within $5\times10^{-7}$ of
$1, 1, 0.918296, 1.655639, 0.811278, 1.5, 1.729574, 1.396241, 1, 1.5$ respectively. Five of these hold with equality.
\end{theorem}

