from collections import Counter
from math import log2

Perm = tuple[int, ...]


def compose(p: Perm, q: Perm) -> Perm:
    return tuple(p[i] for i in q)


def inverse(p: Perm) -> Perm:
    r = [0] * len(p)
    for i, j in enumerate(p):
        r[j] = i
    return tuple(r)


def closure(gens: list[Perm]) -> list[Perm]:
    """Breadth-first closure of a generating set under composition."""
    ident = tuple(range(len(gens[0])))
    seen, frontier = {ident}, [ident]
    while frontier:
        nxt = []
        for x in frontier:
            for g in gens:
                y = compose(g, x)
                if y not in seen:
                    seen.add(y)
                    nxt.append(y)
        frontier = nxt
    return sorted(seen)


def entropy(xs: list) -> float:
    n = len(xs)
    return -sum(c / n * log2(c / n) for c in Counter(xs).values())


def split_type(p: Perm) -> tuple[int, int]:
    """(#fixed points, #points on 2-cycles) = (#roots in F_p, #new roots in F_{p^2})."""
    seen: set[int] = set()
    lengths: list[int] = []
    for i in range(len(p)):
        if i not in seen:
            j, l = i, 0
            while j not in seen:
                seen.add(j)
                j = p[j]
                l += 1
            lengths.append(l)
    return lengths.count(1), 2 * lengths.count(2)


def law_value(gens: list[Perm]) -> float:
    """I(gG' ; type(g)) for g uniform in G = <gens>."""
    G = closure(gens)
    D = closure([compose(compose(a, b), compose(inverse(a), inverse(b))) for a in G for b in G])
    coset = [min(compose(g, h) for h in D) for g in G]
    typ = [split_type(g) for g in G]
    return entropy(coset) + entropy(typ) - entropy(list(zip(coset, typ)))


if __name__ == "__main__":
    print("D4:", round(law_value([(1, 2, 3, 0), (2, 1, 0, 3)]), 6))   # 1.655639
    print("'D4' with adjacent swap:", round(law_value([(1, 2, 3, 0), (1, 0, 2, 3)]), 6))  # 1.0 (S4)

