from collections import Counter
from math import log2


def primes_below(n: int) -> list[int]:
    s = bytearray([1]) * n
    s[0:2] = b"\x00\x00"
    for i in range(2, int(n ** 0.5) + 1):
        if s[i]:
            s[i * i::i] = bytearray(len(s[i * i::i]))
    return [i for i in range(n) if s[i]]


def root_count(p: int) -> int:
    """Roots of x^3 - x - 1 mod p: 0 = inert (3-cycle), 1 = transposition, 3 = split."""
    return sum(1 for x in range(p) if (x ** 3 - x - 1) % p == 0)


def entropy(xs: list) -> float:
    n = len(xs)
    return -sum(c / n * log2(c / n) for c in Counter(xs).values())


def plug_in_channel(ps: list[int], N: int) -> float:
    r = [p % N for p in ps]
    t = [root_count(p) for p in ps]
    return entropy(r) + entropy(t) - entropy(list(zip(r, t)))


if __name__ == "__main__":
    ps = [p for p in primes_below(20000) if p != 23]
    sq = {x * x % 23 for x in range(1, 23)}
    print("dictionary holds:", all((root_count(p) == 1) == (p % 23 not in sq) for p in ps))
    print("three-prime sample {2,5,59}:", plug_in_channel([2, 5, 59], 23), "= log2 3")
    for n in (30, 100, 1000, len(ps)):
        print(n, round(plug_in_channel(ps[:n], 23), 4))

