import random
from collections import Counter
from math import log, log2


def entropy(xs: list) -> float:
    n = len(xs)
    return -sum(c / n * log2(c / n) for c in Counter(xs).values())


def simulate_bias(K: int, n: int, trials: int, seed: int = 20260821) -> tuple[float, float]:
    """Mean plug-in excess of an S3 type channel through a K-class uniform dial
    (K/2 classes over each coset), versus the first-order prediction
    (K_rT - K_r - K_T + 1)/(2 n ln 2) with K_rT = 3K/2, K_r = K, K_T = 3."""
    rng = random.Random(seed)
    tot = 0.0
    for _ in range(trials):
        r = [rng.randrange(K) for _ in range(n)]
        t = [(0 if rng.random() < 1 / 3 else 2) if x < K // 2 else 1 for x in r]
        tot += entropy(r) + entropy(t) - entropy(list(zip(r, t)))
    pred = (3 * K // 2 - K - 3 + 1) / (2 * n * log(2))
    return tot / trials - 1.0, pred


