#!/usr/bin/env python3
"""Joint (coset, type) tables of the master-table groups, with their law values.

Each heatmap shows how the uniform (Chebotarev) law of a Galois group splits over
abelianization cosets (rows) and splitting types (columns). The law value is the
mutual information of this table."""
from __future__ import annotations

from collections import Counter
from math import log2

import matplotlib.pyplot as plt

Perm = tuple[int, ...]


def compose(p: Perm, q: Perm) -> Perm:
    return tuple(p[i] for i in q)


def inverse(p: Perm) -> Perm:
    r = [0] * len(p)
    for i, j in enumerate(p):
        r[j] = i
    return tuple(r)


def closure(gens: list[Perm]) -> list[Perm]:
    ident = tuple(range(len(gens[0])))
    seen, fr = {ident}, [ident]
    while fr:
        nw = []
        for x in fr:
            for g in gens:
                y = compose(g, x)
                if y not in seen:
                    seen.add(y)
                    nw.append(y)
        fr = nw
    return sorted(seen)


def cyc(n: int, *cs: tuple[int, ...]) -> Perm:
    p = list(range(n))
    for c in cs:
        for k in range(len(c)):
            p[c[k]] = c[(k + 1) % len(c)]
    return tuple(p)


def cycle_type(p: Perm) -> tuple[int, ...]:
    seen, out = set(), []
    for i in range(len(p)):
        if i in seen:
            continue
        j, l = i, 0
        while j not in seen:
            seen.add(j)
            j = p[j]
            l += 1
        out.append(l)
    return tuple(sorted(out))


def split(p: Perm) -> str:
    c = cycle_type(p)
    return f"({c.count(1)},{2 * c.count(2)})"


def H(xs: list) -> float:
    n = len(xs)
    return -sum(v / n * log2(v / n) for v in Counter(xs).values())


def main() -> None:
    aff = sorted({tuple((a * x + b) % 5 for x in range(5)) for a in range(1, 5) for b in range(5)})
    groups = {
        "S3": closure([cyc(3, (0, 1, 2)), cyc(3, (0, 1))]),
        "A4": closure([cyc(4, (0, 1, 2)), cyc(4, (0, 1), (2, 3))]),
        "D4": closure([cyc(4, (0, 1, 2, 3)), cyc(4, (0, 2))]),
        "C4": closure([cyc(4, (0, 1, 2, 3))]),
        "D6": closure([cyc(6, (0, 1, 2, 3, 4, 5)), cyc(6, (1, 5), (2, 4))]),
        "F20": aff,
    }
    fig, axes = plt.subplots(2, 3, figsize=(13, 7.5))
    for ax, (name, G) in zip(axes.flat, groups.items()):
        comms = {compose(compose(a, b), compose(inverse(a), inverse(b))) for a in G for b in G}
        D = closure(list(comms))
        cos = [min(compose(g, h) for h in D) for g in G]
        typ = [split(g) for g in G]
        cu, tu = sorted(set(cos)), sorted(set(typ))
        M = [[0] * len(tu) for _ in cu]
        for c, t in zip(cos, typ):
            M[cu.index(c)][tu.index(t)] += 1
        I = H(cos) + H(typ) - H(list(zip(cos, typ)))
        ax.imshow(M, cmap="YlOrBr")
        for i in range(len(cu)):
            for j in range(len(tu)):
                if M[i][j]:
                    ax.text(j, i, M[i][j], ha="center", va="center")
        ax.set_xticks(range(len(tu)), tu, fontsize=8)
        ax.set_yticks(range(len(cu)), [f"coset {k+1}" for k in range(len(cu))], fontsize=8)
        ax.set_title(f"{name}: |G|={len(G)}, law = {I:.6f} bits", fontsize=10)
        ax.set_xlabel("splitting type (#roots in F_p, #new roots in F_p^2)", fontsize=7)
    fig.suptitle("Where the bits come from: joint (coset, type) laws of master-table groups")
    plt.tight_layout()
    plt.savefig("master_table_heatmaps.png", dpi=150)
    print("saved master_table_heatmaps.png")


if __name__ == "__main__":
    main()
